{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is undocumented."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring define a narrow grid-puzzle comparison. The reported score describes one run; missing repeat-run findings prevent assessing score consistency."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "Without repeated observations, stability remains unknown; it is not demonstrated to be poor."
        }
      ],
      "instrument_review": "Exact-grid scoring supports reporting performance on the tested puzzles. The documented single evaluation supplies no evidence of consistency across runs, limiting confidence in repeatable comparisons."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations held the stated conditions constant and reported score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "The repeated evaluations support consistency under the specified conditions and stated stability definition. This evidence remains limited to the tested system, puzzles, and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers evaluated score variation across repeated runs under the stated identical conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum stable range of two percentage points."
        }
      ],
      "instrument_review": "Repeat testing documents a consistency problem under the report's own criterion. A single 70% result cannot adequately represent the reported variation, which limits dependable system comparisons."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation does not establish that repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new instructions add no evidence about score consistency."
        }
      ],
      "instrument_review": "Installation instructions document setup, but leave the consistency evidence unchanged. The single reported result supports only a limited account of performance on these puzzles."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher score on the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the narrow intended use. Exact-grid scoring and fixed instructions support interpreting the reported difference, but repeatability and other potentially relevant resource conditions are not supplied."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended cross-domain use does not supply evidence for a cross-domain conclusion."
        }
      ],
      "instrument_review": "The stated selection purpose exceeds the evidence's scope. Grid-puzzle scores support the narrow observed comparison, while selecting for general intelligence across domains lacks supporting findings."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish an improvement in actual workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial with blinded correctness checks favors A, and the reported difference interval of 12 to 28 percentage points supports that direction."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness findings do not establish an effect on unmeasured safety outcomes."
        }
      ],
      "instrument_review": "The later preregistered randomized trial supplies evidence relevant to choosing assistance for correct decisions in this workshop. Blinded checks and reported uncertainty support interpretation; findings do not establish effects on safety, time, or performance in other workshops."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was distinguished from explicit contradiction, and each case was assessed independently."
}
